import com.leon.saintsdragons.common.world.DragonBiomeMatcher;
import com.leon.saintsdragons.common.world.DragonSpawnRegistry;
import com.mojang.serialization.Codec;
import net.minecraft.core.Holder;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.MobCategory;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.biome.MobSpawnSettings;
import net.minecraftforge.common.world.BiomeModifier;
import net.minecraftforge.common.world.MobSpawnSettingsBuilder;
import net.minecraftforge.common.world.ModifiableBiomeInfo;

public final class AddDragonsBiomeModifier
implements BiomeModifier {
    public static final Codec<AddDragonsBiomeModifier> CODEC = Codec.unit(AddDragonsBiomeModifier::new);

    private AddDragonsBiomeModifier() {
    }

    public void modify(Holder<Biome> biome, BiomeModifier.Phase phase, ModifiableBiomeInfo.BiomeInfo.Builder builder) {
        if (phase != BiomeModifier.Phase.MODIFY) {
            return;
        }
        try {
            for (DragonSpawnRegistry.DragonSpawnEntry entry : DragonSpawnRegistry.getAll()) {
                int weight = entry.weight().getAsInt();
                int minGroupSize = entry.minGroupSize().getAsInt();
                int maxGroupSize = entry.maxGroupSize().getAsInt();
                if (weight <= 0 || !DragonBiomeMatcher.isAllowed(biome, entry.biomeTag())) continue;
                AddDragonsBiomeModifier.addSpawn(builder, entry.category(), entry.entityType().get(), weight, minGroupSize, maxGroupSize);
            }
            if (SaintsDragonsConfig.isMoopSpawningEnabled() && DragonBiomeMatcher.isAllowed(biome, ModTags.Biomes.HAS_MOOP)) {
                AddDragonsBiomeModifier.addSpawn(builder, MobCategory.WATER_AMBIENT, ModEntities.MOOP.get(), SaintsDragonsConfig.MOOP_SPAWN_WEIGHT.get(), SaintsDragonsConfig.MOOP_MIN_GROUP_SIZE.get(), SaintsDragonsConfig.MOOP_MAX_GROUP_SIZE.get());
            }
            if (SaintsDragonsConfig.isMossbackSpawningEnabled() && DragonBiomeMatcher.isAllowed(biome, ModTags.Biomes.HAS_MOSSBACK)) {
                AddDragonsBiomeModifier.addSpawn(builder, MobCategory.CREATURE, ModEntities.MOSSBACK.get(), SaintsDragonsConfig.MOSSBACK_SPAWN_WEIGHT.get(), SaintsDragonsConfig.MOSSBACK_MIN_GROUP_SIZE.get(), SaintsDragonsConfig.MOSSBACK_MAX_GROUP_SIZE.get());
            }
        }
        catch (IllegalStateException illegalStateException) {
            // empty catch block
