public class ForgeIgnivorusPartManager {
    private final Ignivorus dragon;
    private final Map<String, PartConfig> partConfigs = new LinkedHashMap<String, PartConfig>();
    private final Map<String, ForgeDragonPart> parts = new LinkedHashMap<String, ForgeDragonPart>();
    private ForgeDragonPart[] partsArray;
    private static final float STRETCH_FACTOR = 0.75f;

    public ForgeIgnivorusPartManager(Ignivorus dragon) {
        this.dragon = dragon;
        this.initializePartConfigs();
        this.initializeParts();
        this.partsArray = this.parts.values().toArray(new ForgeDragonPart[0]);
    }

