        this.partConfigs.put("rightWing", new PartConfig("rightwing", 4.0f, 2.5f, 0.9f, "rightwingjoint"));
        this.partConfigs.put("leftWingOuter", new PartConfig("leftwingjoint", 8.0f, 3.0f, 0.9f, null));
        this.partConfigs.put("rightWingOuter", new PartConfig("rightwingjoint", 8.0f, 3.0f, 0.9f, null));
        this.partConfigs.put("tail1", new PartConfig("tail1", 2.5f, 2.5f, 0.85f, "tail2"));
        this.partConfigs.put("tail2", new PartConfig("tail2", 2.0f, 2.0f, 0.8f, "tail3"));
        this.partConfigs.put("tail3", new PartConfig("tail3", 1.8f, 1.8f, 0.8f, "tail4"));
        this.partConfigs.put("tail4", new PartConfig("tail4", 3.0f, 2.0f, 0.75f, null));
        this.partConfigs.put("leftFrontLeg", new PartConfig("leftfrontleg", 1.5f, 2.5f, 1.0f, null));
        this.partConfigs.put("rightFrontLeg", new PartConfig("rightfrontleg", 1.5f, 2.5f, 1.0f, null));
        this.partConfigs.put("leftBackLeg", new PartConfig("leftbackleg", 1.5f, 2.5f, 1.0f, null));
        this.partConfigs.put("rightBackLeg", new PartConfig("rightbackleg", 1.5f, 2.5f, 1.0f, null));
    }

